  /**
   * @method
   * @name coinbaseexchange#createOrder
   * @see
   * https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_postorders
   * @description create a trade order
   * @param {string} symbol unified symbol of the market to create an order in
   * @param {string} type 'market' or 'limit'
   * @param {string} side 'buy' or 'sell'
   * @param {float} amount how much of currency you want to trade in units of
   * base currency
   * @param {float} [price] the price at which the order is to be fulfilled, in
   * units of the quote currency, ignored in market orders
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} an [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  createOrder(ccxt::any symbol, ccxt::any type, ccxt::any side,
              ccxt::any amount, ccxt::any price = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any market = this->market(symbol);
                 ccxt::any request = ccxt::dict{
                     {std::string("type"), type},
                     {std::string("side"), side},
                     {std::string("product_id"),
                      ::getValue(market, std::string("id"))},
                 };
                 ccxt::any clientOrderId =
                     this->safeString2(params, std::string("clientOrderId"),
                                       std::string("client_oid"));
                 if (isTrue(!isEqual(clientOrderId, ccxt::any{}))) {
                   ::setValue(request, std::string("client_oid"),
                              clientOrderId);
                 }
                 ccxt::any triggerPrice = this->safeNumberN(
                     params, ccxt::list{std::string("stopPrice"),
                                        std::string("stop_price"),
                                        std::string("triggerPrice")});
                 if (isTrue(!isEqual(triggerPrice, ccxt::any{}))) {
                   ::setValue(request, std::string("stop_price"),
                              this->priceToPrecision(symbol, triggerPrice));
                 }
                 ccxt::any timeInForce =
                     this->safeString2(params, std::string("timeInForce"),
                                       std::string("time_in_force"));
                 if (isTrue(!isEqual(timeInForce, ccxt::any{}))) {
                   ::setValue(request, std::string("time_in_force"),
                              timeInForce);
                 }
                 ccxt::any postOnly =
                     this->safeValue2(params, std::string("postOnly"),
                                      std::string("post_only"), false);
                 if (isTrue(isEqual(postOnly, true))) {
                   ::setValue(request, std::string("post_only"), true);
                 }
                 params = this->omit(params,
                                     ccxt::list{std::string("timeInForce"),
                                                std::string("time_in_force"),
                                                std::string("stopPrice"),
                                                std::string("stop_price"),
                                                std::string("clientOrderId"),
                                                std::string("client_oid"),
                                                std::string("postOnly"),
                                                std::string("post_only"),
                                                std::string("triggerPrice")});
                 if (isTrue(isEqual(type, std::string("limit")))) {
                   ::setValue(request, std::string("price"),
                              this->priceToPrecision(symbol, price));
                   ::setValue(request, std::string("size"),
                              this->amountToPrecision(symbol, amount));
                 } else if (isTrue(isEqual(type, std::string("market")))) {
                   ccxt::any cost = this->safeNumber2(
                       params, std::string("cost"), std::string("funds"));
                   if (isTrue(isEqual(cost, ccxt::any{}))) {
                     if (isTrue(!isEqual(price, ccxt::any{}))) {
                       cost = multiply(amount, price);
                     }
                   } else {
                     params =
                         this->omit(params, ccxt::list{std::string("cost"),
                                                       std::string("funds")});
                   }
                   if (isTrue(!isEqual(cost, ccxt::any{}))) {
                     ::setValue(request, std::string("funds"),
                                this->costToPrecision(symbol, cost));
                   } else {
                     ::setValue(request, std::string("size"),
                                this->amountToPrecision(symbol, amount));
                   }
                 }
                 ccxt::any response = awaitValue(
                     this->privatePostOrders(this->extend(request, params)));
                 //
                 //     {
                 //         "id": "d0c5340b-6d6c-49d9-b567-48c4bfca13d2",
                 //         "price": "0.10000000",
                 //         "size": "0.01000000",
                 //         "product_id": "BTC-USD",
                 //         "side": "buy",
                 //         "stp": "dc",
                 //         "type": "limit",
                 //         "time_in_force": "GTC",
                 //         "post_only": false,
                 //         "created_at": "2016-12-08T20:02:28.53864Z",
                 //         "fill_fees": "0.0000000000000000",
                 //         "filled_size": "0.00000000",
                 //         "executed_value": "0.0000000000000000",
                 //         "status": "pending",
                 //         "settled": false
                 //     }
                 //
                 return this->parseOrder(response, market);
               })
        .share();
  }

  /**
   * @method
   * @name coinbaseexchange#cancelOrder
   * @see
   * https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_deleteorder
   * @description cancels an open order
   * @param {string} id order id
   * @param {string} symbol unified symbol of the market the order was made in
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} An [order structure]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<ccxt::any>
  cancelOrder(ccxt::any id, ccxt::any symbol = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any request = ccxt::dict{};
                 ccxt::any clientOrderId =
                     this->safeString2(params, std::string("clientOrderId"),
                                       std::string("client_oid"));
                 if (isTrue(isEqual(clientOrderId, ccxt::any{}))) {
                   ::setValue(request, std::string("id"), id);
                 } else {
                   ::setValue(request, std::string("client_oid"),
                              clientOrderId);
                   params = this->omit(params,
                                       ccxt::list{std::string("clientOrderId"),
                                                  std::string("client_oid")});
                 }
                 ccxt::any market = ccxt::any{};
                 if (isTrue(!isEqual(symbol, ccxt::any{}))) {
                   market = this->market(symbol);
                   ::setValue(
                       request, std::string("product_id"),
                       ::getValue(
                           market,
                           std::string(
                               "symbol"))); // the request will be more
                                            // performant if you include it
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(clientOrderId, ccxt::any{}))) {
                   response = awaitValue(this->privateDeleteOrdersId(
                       this->extend(request, params)));
                 } else {
                   response =
                       awaitValue(this->privateDeleteOrdersClientClientOid(
                           this->extend(request, params)));
                 }
                 return this->safeOrder(ccxt::dict{
                     {std::string("info"), response},
                 });
               })
        .share();
  }

