  /**
   * @method
   * @name coinbaseexchange#withdraw
   * @description make a withdrawal
   * @see
   * https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_postwithdrawpaymentmethod
   * @see
   * https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_postwithdrawcoinbaseaccount
   * @param {string} code unified currency code
   * @param {float} amount the amount to withdraw
   * @param {string} address the address to withdraw to
   * @param {string} tag
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object} a [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  withdraw(ccxt::any code, ccxt::any amount, ccxt::any address,
           ccxt::any tag = ccxt::any{},
           ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 ccxt::any tagparamsVariable =
                     this->handleWithdrawTagAndParams(tag, params);
                 tag = ::getValue(tagparamsVariable, 0);
                 params = ::getValue(tagparamsVariable, 1);
                 this->checkAddress(address);
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 ccxt::any currency = this->currency(code);
                 ccxt::any request = ccxt::dict{
                     {std::string("currency"),
                      ::getValue(currency, std::string("id"))},
                     {std::string("amount"), amount},
                 };
                 ccxt::any response = ccxt::any{};
                 if (isTrue(inOp(params, std::string("payment_method_id")))) {
                   response =
                       awaitValue(this->privatePostWithdrawalsPaymentMethod(
                           this->extend(request, params)));
                 } else if (isTrue(inOp(params,
                                        std::string("coinbase_account_id")))) {
                   response =
                       awaitValue(this->privatePostWithdrawalsCoinbaseAccount(
                           this->extend(request, params)));
                 } else {
                   ::setValue(request, std::string("crypto_address"), address);
                   if (isTrue(!isEqual(tag, ccxt::any{}))) {
                     ::setValue(request, std::string("destination_tag"), tag);
                   }
                   response = awaitValue(this->privatePostWithdrawalsCrypto(
                       this->extend(request, params)));
                 }
                 if (isTrue(isEqual(response, ccxt::any{}))) {
                   throw ExchangeError(toString(
                       add(add(this->id, std::string(" withdraw() error: ")),
                           this->json(response))));
                 }
                 return this->parseTransaction(response, currency);
               })
        .share();
  }

  virtual ccxt::any parseLedgerEntryType(ccxt::any type) {
    ccxt::any types = ccxt::dict{
        {std::string("transfer"), std::string("transfer")},
        {std::string("match"), std::string("trade")},
        {std::string("fee"), std::string("fee")},
        {std::string("rebate"), std::string("rebate")},
        {std::string("conversion"), std::string("trade")},
    };
    return this->safeString(types, type, type);
  }

  ccxt::any parseLedgerEntry(ccxt::any item,
                             ccxt::any currency = ccxt::any{}) override {
    //  {
    //      "id": "12087495079",
    //      "amount": "-0.0100000000000000",
    //      "balance": "0.0645419900000000",
    //      "created_at": "2021-10-28T17:14:32.593168Z",
    //      "type": "transfer",
    //      "details": {
    //          "from": "2f74edf7-1440-4586-86dc-ae58c5693691",
    //          "profile_transfer_id": "3ef093ad-2482-40d1-8ede-2f89cff5099e",
    //          "to": "dda99503-4980-4b60-9549-0b770ee51336"
    //      }
    //  },
    //  {
    //     "id": "11740725774",
    //     "amount": "-1.7565669701255000",
    //     "balance": "0.0016490047745000",
    //     "created_at": "2021-10-22T03:47:34.764122Z",
    //     "type": "fee",
    //     "details": {
    //         "order_id": "ad06abf4-95ab-432a-a1d8-059ef572e296",
    //         "product_id": "ETH-DAI",
    //         "trade_id": "1740617"
    //     }
    //  }
    ccxt::any id = this->safeString(item, std::string("id"));
    ccxt::any amountString = this->safeString(item, std::string("amount"));
    ccxt::any direction = ccxt::any{};
    ccxt::any afterString = this->safeString(item, std::string("balance"));
    ccxt::any beforeString =
        ccxt::Precise::stringSub(afterString, amountString);
    if (isTrue(ccxt::Precise::stringLt(amountString, std::string("0")))) {
      direction = std::string("out");
      amountString = ccxt::Precise::stringAbs(amountString);
    } else {
      direction = std::string("in");
    }
    ccxt::any amount = this->parseNumber(amountString);
    ccxt::any after = this->parseNumber(afterString);
    ccxt::any before = this->parseNumber(beforeString);
    ccxt::any timestamp =
        this->parse8601(this->safeValue(item, std::string("created_at")));
    ccxt::any type =
        this->parseLedgerEntryType(this->safeString(item, std::string("type")));
    ccxt::any code = this->safeCurrencyCode(ccxt::any{}, currency);
    ccxt::any details =
        this->safeValue(item, std::string("details"), ccxt::dict{});
    ccxt::any account = ccxt::any{};
    ccxt::any referenceAccount = ccxt::any{};
    ccxt::any referenceId = ccxt::any{};
    if (isTrue(isEqual(type, std::string("transfer")))) {
      account = this->safeString(details, std::string("from"));
      referenceAccount = this->safeString(details, std::string("to"));
      referenceId =
          this->safeString(details, std::string("profile_transfer_id"));
    } else {
      referenceId = this->safeString(details, std::string("order_id"));
    }
    ccxt::any status = std::string("ok");
    return this->safeLedgerEntry(
        ccxt::dict{
            {std::string("info"), item},
            {std::string("id"), id},
            {std::string("timestamp"), timestamp},
            {std::string("datetime"), this->iso8601(timestamp)},
            {std::string("direction"), direction},
            {std::string("account"), account},
            {std::string("referenceAccount"), referenceAccount},
            {std::string("referenceId"), referenceId},
            {std::string("type"), type},
            {std::string("currency"), code},
            {std::string("amount"), amount},
            {std::string("before"), before},
            {std::string("after"), after},
            {std::string("status"), status},
            {std::string("fee"), ccxt::any{}},
        },
        currency);
  }

  /**
   * @method
   * @name coinbaseexchange#fetchLedger
   * @description fetch the history of changes, actions done by the user or
   * operations that altered the balance of the user
   * @see
   * https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_getaccountledger
   * @param {string} code unified currency code, default is undefined
   * @param {int} [since] timestamp in ms of the earliest ledger entry, default
   * is undefined
   * @param {int} [limit] max number of ledger entries to return, default is
   * undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {int} [params.until] the latest time in ms to fetch trades for
   * @returns {object} a [ledger structure]{@link
   * https://docs.ccxt.com/?id=ledger-entry-structure}
   */
  std::shared_future<ccxt::any>
  fetchLedger(ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
              ccxt::any limit = ccxt::any{},
              ccxt::any params = ccxt::dict{}) override {
    return std::
        async(std::launch::deferred,
              [=]() mutable -> ccxt::any {
                // https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_getaccountledger
                if (isTrue(isEqual(code, ccxt::any{}))) {
                  throw ArgumentsRequired(toString(add(
                      this->id,
                      std::string(" fetchLedger() requires a code param"))));
                }
                if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                  awaitValue(this->loadMarkets());
                }
                awaitValue(this->loadAccounts());
                ccxt::any currency = this->currency(code);
                ccxt::any accountsByCurrencyCode =
                    this->indexBy(this->accounts, std::string("code"));
                ccxt::any account =
                    this->safeValue(accountsByCurrencyCode, code);
                if (isTrue(isEqual(account, ccxt::any{}))) {
                  throw ExchangeError(toString(add(
                      add(this->id,
                          std::string(
                              " fetchLedger() could not find account id for ")),
                      code)));
                }
                ccxt::any request = ccxt::dict{
                    {std::string("id"), ::getValue(account, std::string("id"))},
                };
                if (isTrue(!isEqual(since, ccxt::any{}))) {
                  ::setValue(request, std::string("start_date"),
                             this->iso8601(since));
                }
                if (isTrue(!isEqual(limit, ccxt::any{}))) {
                  ::setValue(request, std::string("limit"),
                             limit); // default 100
                }
                ccxt::any until = this->safeValue2(params, std::string("until"),
                                                   std::string("end_date"));
                if (isTrue(!isEqual(until, ccxt::any{}))) {
                  params = this->omit(params, ccxt::list{std::string("until")});
                  ::setValue(request, std::string("end_date"),
                             this->iso8601(until));
                }
                ccxt::any response =
                    awaitValue(this->privateGetAccountsIdLedger(
                        this->extend(request, params)));
                ccxt::any entries = this->toArray(response);
                for (ccxt::any i = 0; isLessThan(i, getArrayLength(entries));
                     postFixIncrement(i)) {
                  ::setValue(::getValue(entries, i), std::string("currency"),
                             code);
                }
                return this->parseLedger(entries, currency, since, limit);
              })
            .share();
  }

  /**
   * @method
   * @name coinbaseexchange#fetchDepositsWithdrawals
   * @description fetch history of deposits and withdrawals
   * @see
   * https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_gettransfers
   * @see
   * https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_getaccounttransfers
   * @param {string} [code] unified currency code for the currency of the
   * deposit/withdrawals, default is undefined
   * @param {int} [since] timestamp in ms of the earliest deposit/withdrawal,
   * default is undefined
   * @param {int} [limit] max number of deposit/withdrawals to return, default
   * is undefined
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [::getValue(params, std::string("id"))] account id, when
   * defined, the endpoint used is '/accounts/{account_id}/transfers/' instead
   * of '/transfers/'
   * @returns {object} a list of [transaction structure]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any> fetchDepositsWithdrawals(
      ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
      ccxt::any limit = ccxt::any{}, ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 if (isTrue(isEqual(this->markets, ccxt::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 awaitValue(this->loadAccounts());
                 ccxt::any currency = ccxt::any{};
                 ccxt::any id =
                     this->safeString(params, std::string("id")); // account id
                 if (isTrue(isEqual(id, ccxt::any{}))) {
                   if (isTrue(!isEqual(code, ccxt::any{}))) {
                     currency = this->currency(code);
                     ccxt::any accountsByCurrencyCode =
                         this->indexBy(this->accounts, std::string("code"));
                     ccxt::any account =
                         this->safeValue(accountsByCurrencyCode, code);
                     if (isTrue(isEqual(account, ccxt::any{}))) {
                       throw ExchangeError(toString(add(
                           add(this->id,
                               std::string(" fetchDepositsWithdrawals() could "
                                           "not find account id for ")),
                           code)));
                     }
                     id = ::getValue(account, std::string("id"));
                   }
                 }
                 ccxt::any request = ccxt::dict{};
                 if (isTrue(!isEqual(id, ccxt::any{}))) {
                   ::setValue(request, std::string("id"), id);
                 }
                 if (isTrue(!isEqual(limit, ccxt::any{}))) {
                   ::setValue(request, std::string("limit"), limit);
                 }
                 ccxt::any response = ccxt::any{};
                 if (isTrue(isEqual(id, ccxt::any{}))) {
                   ccxt::any transfers = awaitValue(this->privateGetTransfers(
                       this->extend(request, params)));
                   //
                   //    [
                   //        {
                   //            "id": "bee6fd7c-afb2-4e47-8298-671d09997d16",
                   //            "type": "deposit",
                   //            "created_at": "2022-12-21 00:48:45.477503+00",
                   //            "completed_at": null,
                   //            "account_id":
                   //            "sal3802-36bd-46be-a7b8-alsjf383sldak",
                   //            "user_id": "6382048209f92as392039dlks2",
                   //            "amount": "0.01000000",
                   //            "details": {
                   //                "network": "litecoin",
                   //                "crypto_address":
                   //                "MKemtnCFUYKsNWaf5EMYMpwSszcXWFDtTY",
                   //                "coinbase_account_id":
                   //                "fl2b6925-f6ba-403n-jj03-40fl435n430f",
                   //                "coinbase_transaction_id":
                   //                "63a25bb13cb5cf0001d2cf17", // withdrawals
                   //                only "crypto_transaction_hash":
                   //                "752f35570736341e2a253f7041a34cf1e196fc56128c900fd03d99da899d94c1",
                   //                "tx_service_transaction_id": "1873249104",
                   //                "coinbase_payment_method_id": ""
                   //            },
                   //            "canceled_at": null,
                   //            "processed_at": null,
                   //            "user_nonce": null,
                   //            "idem": "5e3201b0-e390-5k3k-a913-c32932049242",
                   //            "profile_id":
                   //            "k3k302a8-c4dk-4f49-9d39-3203923wpk39",
                   //            "currency": "LTC"
                   //        }
                   //    ]
                   //
                   response = this->toArray(transfers);
                   for (ccxt::any i = 0;
                        isLessThan(i, getArrayLength(response));
                        postFixIncrement(i)) {
                     ccxt::any account_id = this->safeString(
                         ::getValue(response, i), std::string("account_id"));
                     ccxt::any account =
                         this->safeValue(this->accountsById, account_id);
                     ccxt::any codeInner =
                         this->safeString(account, std::string("code"));
                     ::setValue(::getValue(response, i),
                                std::string("currency"), codeInner);
                   }
                 } else {
                   ccxt::any accountTransfers =
                       awaitValue(this->privateGetAccountsIdTransfers(
                           this->extend(request, params)));
                   //
                   //    [
                   //        {
                   //            "id": "bee6fd7c-afb2-4e47-8298-671d09997d16",
                   //            "type": "deposit",
                   //            "created_at": "2022-12-21 00:48:45.477503+00",
                   //            "completed_at": null,
                   //            "amount": "0.01000000",
                   //            "details": {
                   //                "network": "litecoin",
                   //                "crypto_address":
                   //                "MKemtnCFUYKsNWaf5EMYMpwSszcXWFDtTY",
                   //                "coinbase_account_id":
                   //                "fl2b6925-f6ba-403n-jj03-40fl435n430f",
                   //                "coinbase_transaction_id":
                   //                "63a25bb13cb5cf0001d2cf17", // withdrawals
                   //                only "crypto_transaction_hash":
                   //                "752f35570736341e2a253f7041a34cf1e196fc56128c900fd03d99da899d94c1",
                   //                "tx_service_transaction_id": "1873249104",
                   //                "coinbase_payment_method_id": ""
                   //            },
                   //            "canceled_at": null,
                   //            "processed_at": null,
                   //            "user_nonce": null,
                   //            "idem": "5e3201b0-e390-5k3k-a913-c32932049242",
                   //            "profile_id":
                   //            "k3k302a8-c4dk-4f49-9d39-3203923wpk39",
                   //            "currency": "LTC"
                   //        }
                   //    ]
                   //
                   response = this->toArray(accountTransfers);
                   for (ccxt::any i = 0;
                        isLessThan(i, getArrayLength(response));
                        postFixIncrement(i)) {
                     ::setValue(::getValue(response, i),
                                std::string("currency"), code);
                   }
                 }
                 return this->parseTransactions(response, currency, since,
                                                limit);
               })
        .share();
  }

  /**
   * @method
   * @name coinbaseexchange#fetchDeposits
   * @description fetch all deposits made to an account
   * @see
   * https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_gettransfers
   * @see
   * https://docs.cloud.coinbase.com/exchange/reference/exchangerestapi_getaccounttransfers
   * @param {string} code unified currency code
   * @param {int} [since] the earliest time in ms to fetch deposits for
   * @param {int} [limit] the maximum number of deposits structures to retrieve
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @returns {object[]} a list of [transaction structures]{@link
   * https://docs.ccxt.com/?id=transaction-structure}
   */
  std::shared_future<ccxt::any>
  fetchDeposits(ccxt::any code = ccxt::any{}, ccxt::any since = ccxt::any{},
                ccxt::any limit = ccxt::any{},
                ccxt::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> ccxt::any {
                 return awaitValue(this->fetchDepositsWithdrawals(
                     code, since, limit,
                     this->extend(
                         ccxt::dict{
                             {std::string("type"), std::string("deposit")},
                         },
                         params)));
               })
        .share();
  }

